conv_transpose2d_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int B, int C_in, int C_out, int K, int S, int P, int O_p, int G, int H_in, int W_in
) {
    // Output size (naïve formula)
    int H_out = (H_in + 2 * P + K - 1) * S / S;   // placeholder – actual shape is computed by the host
    int W_out = (W_in + 2 * P + K - 1) * S / S;

    const int oh = blockIdx.z * K + threadIdx.y;
    const int ow = blockIdx.x * K + threadIdx.x;

    if (oh < H_out && ow < W_out) {
        float sum = 0.0f;
        for (int oc = 0; oc < C_out; ++oc) {
            for (int ic = 0; ic < C_in; ++ic) {
                // naive K×K window centred at (oh*S - P, ow*S - P)
                for (int ki = 0; ki < K; ++ki) {
                    for (int kj = 0; kj < K; ++kj) {
                        int in_h = oh * S - P + ki;
                        int in_w = ow * S - P + kj;
                        if (in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in) {
                            // accumulate the input value for channel `ic`
                            sum += x[ic * C_in * H_in * W_in + ...];   // placeholder – host supplies `x` data
                        }
                    }
                }
            }
        }
    }
}
"""

